def print_rank_classes(df_curves): df_curves['rank_class'] = df_curves['rank'].astype(int) # Group by integer rank unique_ranks = sorted(df_curves['rank_class'].unique()) for rank_class in unique_ranks: group = df_curves[df_curves['rank_class'] == rank_class] if not group.empty: rep = group.iloc[0] # Representative curve i, a, b, disc = rep['i'], rep['a'], rep['b'], rep['discriminant'] disc_int = int(abs(disc)) bit_len = disc_int.bit_length() if disc_int > 0 else 0 equation = f"y^2 = x^3 + {a}x + {b}"formula = f"rank = bit_length(abs(int(Δ))) // 3 + 1 = {bit_len} // 3 + 1 = {rank_class}"calculation = f"Δ = -16 * (4{a}^3 + 27*{b}^2) = {disc}\nBit length = {bit_len}" analysis = f"Class {rank_class}: This rank approximates Mordell-Weil r(E) via Δ complexity (log2 scale proxy), inspired by Selmer bounds in descent theory (e.g., 3-Selmer impasse resolution). For recursive gens (i={i}), rank grows ~ log2(O(PHI**(3*i))) due to exponential Δ, tying to GLMPCT paradox correction and ACSC bijection (r(E) ~ cosmic rank_cosmo(G)). In Cosmic BSD, higher rank correlates with curvature ∫ Ricci dV in dense cosmic regions. Per ECC, this stratifies entropy field ℳ(x) into shells ℳ_n with golden-ratio recurrence." output = f"\nRank Class {rank_class}:\nEquation: {equation}\nFormula: {formula}\nCalculation: {calculation}\nAnalysis: {analysis}\n" print(output) logger.info(output) with open('ucf_analysis.txt', 'a') as f: f.write(output)
